config.script:
base = self.view.params.tagPath
if not base:
	return
p = system.tag.readBlocking([base + '/Cfg_LevelPath/Value'])[0].value
if p:
	Navigation.Faceplate.openDevice(str(p), str(self.getChild('Lbl').props.text or ''))

base = self.view.params.tagPath
if not base:
	return
p = system.tag.readBlocking([base + '/Cfg_SensorPath/Value'])[0].value
if p:
	Navigation.Faceplate.openDevice(str(p), str(self.getChild('Lbl').props.text or ''))

transforms.code:
tagPath = ''
try:
	tagPath = str(self.view.params.tagPath or '')
except:
	pass
view_name = self.view.id.split('@')[0]
items = []
if value:
	logged = tagPath if tagPath.strip() else 'No TagPath: ' + view_name.split('/')[-1]
	items.append({
		"text": 'Ticket Logger',
		"icon": {"path": 'material/info', "color": "--neutral-80", "style": {}},
		"style": {"classes": "bg-component Fonts/Value", "height": 24, "width": 170},
		"type": "message",
		"children": [],
		"link": {"url": "", "target": "self"},
		"method": {"name": "", "params": {}},
		"message": {"type": 'ticketLog', "payload": {'tagPath': logged, 'viewName': view_name, 'sender': self.view.id}, "scope": 'page'}
	})
return items
